ALTER TABLE public.activity_items DROP CONSTRAINT activity_items_check; ALTER TABLE public.recurring_tasks DROP CONSTRAINT recurring_tasks_check;
CREATE OR REPLACE FUNCTION public.activity_backup_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid;BEGIN SELECT cp.pipeline_id INTO pid FROM activity_plans ap JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id WHERE ap.id=NEW.plan_id;IF NEW.backup_id IS NULL THEN NEW.backup_id:=pipeline_default_backup(pid);END IF;IF NEW.owner_id=NEW.backup_id AND NOT is_pipeline_head(NEW.owner_id,pid) THEN RAISE EXCEPTION 'Only the pipeline head may be both owner and default backup';END IF;RETURN NEW;END $$;
CREATE TRIGGER activity_backup_guard BEFORE INSERT OR UPDATE ON public.activity_items FOR EACH ROW EXECUTE FUNCTION public.activity_backup_guard();CREATE TRIGGER activity_backup_guard BEFORE INSERT OR UPDATE ON public.recurring_tasks FOR EACH ROW EXECUTE FUNCTION public.activity_backup_guard();REVOKE ALL ON FUNCTION public.activity_backup_guard() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f text;BEGIN
SELECT pg_get_functiondef('public.save_activity_plan(uuid,date,jsonb,uuid,boolean)'::regprocedure) INTO f;f:=replace(f,'own=bak OR','(own=bak AND NOT is_pipeline_head(own,cp.pipeline_id)) OR');f:=replace(f,'))<>2 THEN RAISE', '))<>(CASE WHEN own=bak THEN 1 ELSE 2 END) THEN RAISE');EXECUTE f;
SELECT pg_get_functiondef('public.update_recurring_task(uuid,text,date,text,uuid,uuid)'::regprocedure) INTO f;f:=replace(f,'coalesce(_owner,t.owner_id)=coalesce(_backup,t.backup_id) OR','(coalesce(_owner,t.owner_id)=coalesce(_backup,t.backup_id) AND NOT is_pipeline_head(coalesce(_owner,t.owner_id),cp.pipeline_id)) OR');f:=replace(f, ')))<>2 THEN RAISE', ')))<>(CASE WHEN coalesce(_owner,t.owner_id)=coalesce(_backup,t.backup_id) THEN 1 ELSE 2 END) THEN RAISE');EXECUTE f;
SELECT pg_get_functiondef('public.get_my_launch()'::regprocedure) INTO f;f:=replace(f,'t.status = ''waiting_client''','(t.status = ''waiting_client'' OR (t.status = ''blocked'' AND t.blocker_reason = ''Waiting on client approval''))');EXECUTE f;
SELECT pg_get_functiondef('public.queue_blocker_reminders(timestamptz)'::regprocedure) INTO f;f:=replace(f,'lower(email) IN(''mohnish@group2001.in'',''alcorgetaways@gmail.com'')','lower(email) = ''mohnish@group2001.in''');EXECUTE f;
END $$;